INSERT INTO `cards` (`id`, `pagina_id`, `html`, `pos_left`, `pos_top`, `width`, `height`, `class_name`, `sort_order`, `state_json`, `created_at`, `card_id`) VALUES
(24999, 16381, '<h1 style=\"cursor: pointer;\" class=\"\" c>Título H1 (Selecione uma palavra, Shift+Clique para marcar alvos)</h1>', '120px', '340px', '900px', 'auto', 'editable-item', 0, NULL, '2026-08-30 20:34:06', 'card_24999'),
(25000, 16381, '<h6 style=\"cursor: pointer;\">Título H6 (Selecione uma palavra, Shift+Clique para marcar alvos)</h6>', '480px', '100px', 'auto', 'auto', 'editable-item', 1, NULL, '2026-08-30 20:34:06', 'card_25000'),
(1403728, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 180px; top: 20px; width: 780px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788756531204_szei7h\" data-initialized=\"true\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Lógica Bi Dimensional (Hardware x Software)</h3><p style=\"cursor: pointer;\" class=\"\">um computador é um conjunto de dois tipos de coisas, circuitos e sistemas digitais. <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">portanto todo</span> hardware deve ter um software que o controlara, então o hardware provem processamento, enquanto o software administra e controla o processamento&nbsp;</p></div></div>', '180px', '20px', '780px', 'auto', 'editable-item', 0, NULL, '2026-10-05 23:14:08', 'card_1788756531204_szei7h'),
(1403729, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 60px; top: 320px; width: 500px; height: auto; overflow: visible;\" data-card-id=\"card_1788756576629_rgoikw\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Software (SW)</h3><p style=\"cursor: pointer;\" class=\"\">O software é a parte que administra o processamento, portanto é a parte lógica do computador, ele dá uma função para o computador</p></div></div>', '60px', '320px', '500px', 'auto', 'editable-item', 1, NULL, '2026-10-05 23:14:08', 'card_1788756576629_rgoikw'),
(1403730, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 580px; top: 320px; width: 500px; height: auto;\" data-card-id=\"card_1788756586330_db49vk\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Hardware (<span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">HW</span>)</h3><p style=\"cursor: pointer;\" class=\"\" c=\"\">É a parte física do computador, é o conjunto placa mãe, processador, memoria ram, ssd/<span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">hd</span>, fonte, etc.</p></div></div>', '580px', '320px', '500px', 'auto', 'editable-item', 2, NULL, '2026-10-05 23:14:08', 'card_1788756586330_db49vk'),
(1403731, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 1560px; top: 580px; width: auto; max-width: 90%; height: auto;\" data-initialized=\"true\" data-card-id=\"card_1788756613779_1wgvpi\"><h1 style=\"cursor: pointer;\" class=\"\">Componentes principiais</h1></div>', '1560px', '580px', 'auto', 'auto', 'editable-item', 3, NULL, '2026-10-05 23:14:08', 'card_1788756613779_1wgvpi'),
(1403732, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 980px; top: 840px; width: 500px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788756634182_4us57a\" data-initialized=\"true\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Processador (CPU)</h3><p style=\"cursor: pointer;\" class=\"\">Unidade de processamento do computador, serve para executar instruções dada pelo software de forma sequencial</p></div></div>', '980px', '840px', '500px', 'auto', 'editable-item', 4, NULL, '2026-10-05 23:14:08', 'card_1788756634182_4us57a'),
(1403733, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 1500px; top: 840px; width: 580px; height: auto;\" data-card-id=\"card_1788756675958_vji6na\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\" c=\"\">Memória Principal (RAM)</h3><p style=\"cursor: pointer;\" class=\"\" c=\"\">Server para mediar a comunicação do ssd/hd e processador, sendo uma memoria temporaria, tudo que o é aberto no computador é deslocado até a memoria ram, e o processador usa a memoria <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">ram</span> como \"livraria\", as informações são separadas em micro células de 1 byte (8bits) onde cada célula tem seu endereço único.</p></div></div>', '1500px', '840px', '580px', 'auto', 'editable-item', 5, NULL, '2026-10-05 23:14:08', 'card_1788756675958_vji6na'),
(1403734, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 2120px; top: 860px; width: 580px; height: auto;\" data-card-id=\"card_1788756688591_gl3m4g\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Placa-Mãe (<span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">Motherboard</span>)</h3><p style=\"cursor: pointer;\" class=\"\">Serve como espinha dorsal do computador, é o elemento que une todas as peças do computador em um desktop.</p></div></div>', '2120px', '860px', '580px', 'auto', 'editable-item', 6, NULL, '2026-10-05 23:14:08', 'card_1788756688591_gl3m4g'),
(1403735, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 980px; top: 1060px; width: 500px; height: auto;\" data-card-id=\"card_1788756732619_7mx23k\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer; text-align: center;\" c=\"\"><span style=\"\"><span style=\"white-space: pre-wrap; font-family: Arial, sans-serif;\"><span style=\"font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\"><span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">Clock</span> (Hz/GHz):</span></span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap;\"> Frequência de pulsos. Quanto maior, mais instruções são processadas por segundo (teoricamente). O Overclocking é uma prática que força o CPU além do padrão da fabricante, tentando extrair um maior desempenho</span></span></li></ul></div>', '980px', '1060px', '500px', 'auto', 'editable-item drag-over', 7, NULL, '2026-10-05 23:14:08', 'card_1788756732619_7mx23k'),
(1403736, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 980px; top: 1260px; width: 500px; height: auto;\" data-card-id=\"card_1788757025857_c12awk\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer; text-align: left;\" c=\"\"><span style=\"\"><span style=\"font-weight: bolder; text-align: start; white-space: pre-wrap;\">Núcleos (Cores):</span><span style=\"font-weight: bolder; color: rgb(220, 220, 220); text-align: start; white-space: pre-wrap;\"> </span>um Processador é separado em mini núcleos, uma solução adotada para limitar o clock, bom, invés de desenvolver um núcleo com um <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">clock</span> gigantesco, podemos dividir o processamento em mini núcleos, assim distribuindo a carga de processamento</span></li></ul></div>', '980px', '1260px', '500px', 'auto', 'editable-item drag-over', 8, NULL, '2026-10-05 23:14:08', 'card_1788757025857_c12awk'),
(1403737, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 980px; top: 1500px; width: 500px; height: auto;\" data-card-id=\"card_1788757055750_2ka13w\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Cache:</span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap;\"> memoria interna que ajuda a armazenar temporariamente os dados para distribuir entre os núcleos e <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">dps</span> enviar a outros setores do computador</span></span></li></ul></div>', '980px', '1500px', '500px', 'auto', 'editable-item drag-over', 9, NULL, '2026-10-05 23:14:08', 'card_1788757055750_2ka13w'),
(1403738, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 980px; top: 1680px; width: 500px; height: auto;\" data-card-id=\"card_1788757075479_xd3og1\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer; text-align: left;\" c=\"\"><span style=\"\"><span style=\"font-weight: bolder; white-space: pre-wrap;\">Pinagem:</span><span style=\"font-weight: bolder; color: rgb(255, 255, 255); white-space: pre-wrap;\"> </span>É o tipo de socket q o processador vai usar, bom, cada geração de socket tem um formato distinto, isso é dependente da fabricante, a placa mãe é compátivel com um processador se o socket fêmea for compativel com o processador, portanto só uma placa-mãe com socket 1155 pode comportar um processador 1155, entretanto, a compatibilidade tbm depende do chip-set da placa mãe, mas no geral, a pinagem é apenas o âmbito de formato e <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">socket</span>.</span></li></ul></div>', '980px', '1680px', '500px', 'auto', 'editable-item drag-over', 10, NULL, '2026-10-05 23:14:08', 'card_1788757075479_xd3og1'),
(1403739, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 1500px; top: 1140px; width: 580px; height: auto; overflow: visible;\" data-card-id=\"card_1788757103970_1muj2f\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer; text-align: left;\" c=\"\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Estrutura: </span><span style=\"color: rgb(220, 220, 220); font-size: 1rem; white-space: pre-wrap; font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">Funciona como um enorme <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">grid</span> de&nbsp;células&nbsp;(caixas de correio). Cada célula guarda 1&nbsp;byte&nbsp;(8 bits) e possui um&nbsp;endereço único. O processador pode acessar qualquer célula em qualquer ordem (daí vem o nome \"Acesso Aleatório\").</span></span></li></ul></div>', '1500px', '1140px', '580px', 'auto', 'editable-item drag-over', 11, NULL, '2026-10-05 23:14:08', 'card_1788757103970_1muj2f'),
(1403740, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 1500px; top: 1340px; width: 580px; height: auto;\" data-card-id=\"card_1788757127842_gi7hxy\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Volatilidade: </span><span style=\"color: rgb(220, 220, 220); font-size: 1rem; white-space: pre-wrap; font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">volátil. Assim que o computador é desligado ou falta energia, toda a luz elétrica que mantém os bits some, e os dados são&nbsp;apagados completamente. Por isso você precisa salvar os arquivos no HD/SSD.</span></span></li></ul></div>', '1500px', '1340px', '580px', 'auto', 'editable-item drag-over', 12, NULL, '2026-10-05 23:14:08', 'card_1788757127842_gi7hxy'),
(1403741, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 1500px; top: 1520px; width: 580px; height: auto;\" data-card-id=\"card_1788757161225_zte0at\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Capacidade: </span><span style=\"color: rgb(220, 220, 220); font-size: 1rem; white-space: pre-wrap; font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">Medida em&nbsp;GB (gigabytes). Exemplo: 8 GB de RAM significa 8 bilhões de células disponíveis para armazenar dados temporários.</span></span></li></ul></div>', '1500px', '1520px', '580px', 'auto', 'editable-item drag-over', 13, NULL, '2026-10-05 23:14:08', 'card_1788757161225_zte0at'),
(1403742, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 1500px; top: 1680px; width: 580px; height: auto; overflow: visible;\" data-card-id=\"card_1788757176986_q5j030\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Velocidade (Taxa de transferência): </span><span style=\"color: rgb(220, 220, 220); font-size: 1rem; white-space: pre-wrap; font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">Medida em&nbsp;GB (gigabytes). Exemplo: 8 GB de RAM significa 8 bilhões de células disponíveis para armazenar dados temporários.</span></span></li></ul></div>', '1500px', '1680px', '580px', 'auto', 'editable-item drag-over', 14, NULL, '2026-10-05 23:14:08', 'card_1788757176986_q5j030'),
(1403743, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 2100px; top: 1080px; width: 580px; height: auto; overflow: visible;\" data-card-id=\"card_1788757245678_1iy9si\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Barramentos (Buses):</span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap;\"> </span><span style=\"color: rgb(249, 250, 251); font-size: 1rem; font-family: quote-cjk-patch, Inter, system-ui, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen, Ubuntu, Cantarell, &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, sans-serif;\"><span style=\"font-family: Helvetica, sans-serif;\"><span style=\"font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">São os canais de comunicação (vias de dados) que ligam os componentes. A placa-mãe gerencia a velocidade e o fluxo de informações que passam por esses barramentos (ex: barramento do processador, barramento de vídeo PCI Express).</span></span></span></span></li></ul></div>', '2100px', '1080px', '580px', 'auto', 'editable-item drag-over', 15, NULL, '2026-10-05 23:14:08', 'card_1788757245678_1iy9si'),
(1403744, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 2100px; top: 1300px; width: 580px; height: auto;\" data-card-id=\"card_1788757264922_6940ll\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Integração:</span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap;\"> </span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap; font-family: Arial, sans-serif;\"><span style=\"font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">Com o avanço da tecnologia, a placa-mãe atual já vem com muitas funções que antes eram placas separadas, como: placa de vídeo (onboard), placa de rede (<span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">Ethernet</span> e Wi-Fi), placa de som e portas USB.</span></span></span></li></ul></div>', '2100px', '1300px', '580px', 'auto', 'editable-item drag-over', 16, NULL, '2026-10-05 23:14:08', 'card_1788757264922_6940ll'),
(1403745, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 2100px; top: 1500px; width: 580px; height: auto;\" data-card-id=\"card_1788757307814_1kk5cr\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"font-weight: bolder; color: rgb(86, 156, 214); white-space: pre-wrap;\">Integração:</span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap;\"> </span><span style=\"color: rgb(220, 220, 220); white-space: pre-wrap; font-family: Arial, sans-serif;\"><span style=\"font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">Com o avanço da tecnologia, a placa-mãe atual já vem com muitas funções que antes eram placas separadas, como: placa de vídeo (onboard), placa de rede (<span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">Ethernet</span> e Wi-Fi), placa de som e portas USB.</span></span></span></li></ul></div>', '2100px', '1500px', '580px', 'auto', 'editable-item drag-over', 17, NULL, '2026-10-05 23:14:08', 'card_1788757307814_1kk5cr'),
(1403746, 284978, '<div class=\"editable-item drag-over\" style=\"position: absolute; left: 2100px; top: 1700px; width: 580px; height: auto;\" data-card-id=\"card_1788758077685_7rcbxb\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center active-editing\" style=\"cursor: pointer; text-align: left;\"><span style=\"\"><span style=\"white-space: pre-wrap; font-weight: bolder; color: rgb(86, 156, 214);\">Nos celulares (Smartphones):</span><span style=\"white-space: pre-wrap; color: rgb(220, 220, 220);\"> </span><span style=\"font-size: 1rem; white-space: pre-wrap; color: rgb(220, 220, 220); font-family: &quot;Share Tech Mono&quot;, Courier, monospace;\">A placa-mãe é um circuito altamente compacto e complexo. Nela, o processador, a memória, a controladora de tela&nbsp;touch, o acelerômetro, o GPS e o modem de rede celular ficam todos soldados e integrados em um único espaço minúsculo.</span></span></li></ul></div>', '2100px', '1700px', '580px', 'auto', 'editable-item drag-over', 18, NULL, '2026-10-05 23:14:08', 'card_1788758077685_7rcbxb'),
(1403747, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 60px; top: 580px; width: 500px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788804791484_nkwbtr\" data-initialized=\"true\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Software de Aplicação (finalístico):</h3><p style=\"cursor: pointer; text-align: left;\" class=\"\">São os programas que o usuário usa conscientemente para fazer tarefas específicas.&nbsp;<span style=\"font-size: 1rem; letter-spacing: 0.03em; text-indent: 1.5em; word-spacing: 0.05em;\">Exemplos: Navegadores (Chrome), Planilhas (Excel), Editores de texto (Word) e Jogos (<span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">LoL</span>).</span></p></div></div>', '60px', '580px', '500px', 'auto', 'editable-item', 19, NULL, '2026-10-05 23:14:08', 'card_1788804791484_nkwbtr'),
(1403748, 284978, '<div class=\"editable-item\" style=\"position: absolute; left: 40px; top: 920px; width: 500px; height: auto;\" data-card-id=\"card_1788804848696_q1bfhw\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\">Software de Sistema:</h3><p style=\"cursor: pointer; text-align: left;\" class=\"\">São os programas que criam a ponte entre o hardware e os softwares de aplicação. Eles escondem as diferenças entre máquinas e garantem que tudo funcione.</p><div style=\"cursor: pointer;\">Incluem: Drivers (controlam periféricos como placa de rede) e, principalmente, o Sistema Operacional (o chefe de todos eles).</div><p style=\"cursor: pointer;\"></p></div></div>', '40px', '920px', '500px', 'auto', 'editable-item', 20, NULL, '2026-10-05 23:14:08', 'card_1788804848696_q1bfhw'),
(1403749, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 20px; top: 40px; width: 620px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788805837152_hdts6d\" data-initialized=\"true\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\" c=\"\">Sistema operacional (Oque é)</h3><p style=\"cursor: pointer;\" class=\"\" c=\"\">O sistema operacional é a engrenagem mãe da usabilidade do computador, ela gerencia o hardware de forma que as tarefas sejam executadas, mantendo um equilíbrio entre uso de hardware e as aplicações, também tem <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">diversas funcionalidade</span> de compatibilidade, porém isso já vem implantado no conceito de sistema operacional.</p></div></div>', '20px', '40px', '620px', 'auto', 'editable-item', 0, NULL, '2026-10-05 23:14:08', 'card_1788805837152_hdts6d'),
(1403750, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 200px; top: 340px; width: 260px; max-width: 90%; height: auto; overflow: visible;\" data-initialized=\"true\" data-card-id=\"card_1788806169261_v852xl\"><h3 style=\"cursor: pointer; text-align: center;\" class=\"\" c=\"\">Linha do tempo</h3></div>', '200px', '340px', '260px', 'auto', 'editable-item', 1, NULL, '2026-10-05 23:14:08', 'card_1788806169261_v852xl'),
(1403751, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 80px; top: 480px; width: 500px; height: auto; overflow: visible;\" data-card-id=\"card_1788806191129_6qxoxw\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer; text-align: center;\" class=\"\" c=\"\">A Linha do Tempo (os marcos que você precisa saber):</h3><p style=\"cursor: pointer;\" class=\"\" c=\"\">?️ Unix (1969): Criado na Bell Labs. Não foi o primeiro SO da história, mas foi o mais revolucionário. Foi reescrito em linguagem C, tornando-se portável (rodava em qualquer máquina). É o avô do Linux, macOS e Android.</p><p style=\"cursor: pointer;\"><br style=\"\"></p><p style=\"cursor: pointer;\" class=\"\" c=\"\">? MS-DOS (1981): A Microsoft comprou o QDOS e licenciou para a IBM. Simples, limitado (tela preta, um programa por vez), mas popularizou o computador pessoal. Veio do CP/M, e NÃO do Unix.</p><div style=\"cursor: pointer;\"><br style=\"\"></div><p style=\"cursor: pointer;\" class=\"\" c=\"\">?️ Salto Gráfico (Windows/Mac): A interface com janelas e mouse transformou o computador em algo acessível para qualquer pessoa, dominando a era dos PCs.</p><div style=\"cursor: pointer;\"><br style=\"\"></div><p style=\"cursor: pointer;\" class=\"\" c=\"\">? Revolução Móvel (iOS e Android): Levaram o SO para a palma da mão, com foco em toque, sensores, bateria e mobilidade. Esse é o marco mais importante entre o MS-DOS e as tendências de hoje!</p><div style=\"cursor: pointer;\"><br style=\"\"></div><div style=\"cursor: pointer;\"><br style=\"\"></div><p style=\"cursor: pointer;\"></p></div></div>', '80px', '480px', '500px', 'auto', 'editable-item', 2, NULL, '2026-10-05 23:14:08', 'card_1788806191129_6qxoxw'),
(1403752, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 80px; top: 1340px; width: 500px; height: auto;\" data-card-id=\"card_1788806791289_gfpmnc\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer; text-align: center;\" class=\"\" c=\"\">Tendências</h3><p style=\"cursor: pointer;\" class=\"\" c=\"\">Após um salto na evolução dos sistemas operacionais, tecnologias emergentes se tornaram cada vez mais presentes vemos isso com os (IOT) computação em nuvem (Cloud computing), internet das coisas e ia</p></div></div>', '80px', '1340px', '500px', 'auto', 'editable-item', 3, NULL, '2026-10-05 23:14:08', 'card_1788806791289_gfpmnc'),
(1403753, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 60px; width: auto; max-width: 90%; height: auto;\" data-initialized=\"true\" data-card-id=\"card_1788807724008_xcgb44\"><h3 style=\"cursor: pointer;\" class=\"\" c=\"\">As 3 principais tarefas do Sistema Operacional</h3></div>', '700px', '60px', 'auto', 'auto', 'editable-item', 4, NULL, '2026-10-05 23:14:08', 'card_1788807724008_xcgb44'),
(1403754, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 160px; width: 640px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788807789796_7tmfvm\" data-initialized=\"true\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer;\" c=\"\"><span style=\"\"><strong style=\"\">Gerencia a RAM:</strong>&nbsp;Ele aloca as arquivos do programa em execução na memoria ram, administrando que sai e quem fica dentro do espaço limitado da memoria, mantendo a estabilidade do sistema.</span></li></ul></div>', '700px', '160px', '640px', 'auto', 'editable-item', 5, NULL, '2026-10-05 23:14:08', 'card_1788807789796_7tmfvm'),
(1403755, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 320px; width: 640px; height: auto;\" data-card-id=\"card_1788808191826_72d9wu\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer;\" c=\"\"><span style=\"\"><strong style=\"\">Gerente De Execução:</strong>&nbsp;Com multíplas tarefas em execução simultaneamente o SO administra quem tem prioridade nas execuções, isso limita uso de Ram e Cpu, assim mantendo tudo em pleno funcionamento, sem que seja necessário fechar tarefas necessárias pelo usuário.</span></li></ul></div>', '700px', '320px', '640px', 'auto', 'editable-item', 6, NULL, '2026-10-05 23:14:08', 'card_1788808191826_72d9wu'),
(1403756, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 520px; width: 640px; height: auto;\" data-card-id=\"card_1788808572762_b2g99d\"><ul class=\"styled-list list-group\" style=\"\"><li class=\"list-group-item d-flex justify-content-between align-items-center\" style=\"cursor: pointer;\" c=\"\"><span style=\"\"><strong style=\"\">O Scheduler:</strong>&nbsp;É um subsistema chamado Escalador. ele é o guarda de transito, que controla a fila de processos da (CPU).</span></li></ul></div>', '700px', '520px', '640px', 'auto', 'editable-item', 7, NULL, '2026-10-05 23:14:08', 'card_1788808572762_b2g99d'),
(1403757, 284979, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 660px; width: 640px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788808842730_q36tx5\" data-initialized=\"true\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer;\" class=\"\" c=\"\">O papel da Bios</h3><p style=\"cursor: pointer;\" class=\"\" c=\"\">a bios é um chip q fica alocado na placa-mãe, ela armazena as predefinições basicas de hardware, ela seta qual o dispositivo de armazenamento primário, dando partida para o computador iniciar o sistema partir dele, ele n roda o sistema mas dá o arranque para que as coisas comecem a funcionar.</p></div></div>', '700px', '660px', '640px', 'auto', 'editable-item', 8, NULL, '2026-10-05 23:14:08', 'card_1788808842730_q36tx5'),
(1403758, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 600px; top: 40px; width: auto; max-width: 90%; height: auto;\" data-card-id=\"card_1788571380593_ckd4ab\" data-initialized=\"true\"><p style=\"padding: 8px; margin: 0px; cursor: pointer;\" class=\"\"><span style=\"font-size: 2.5rem; font-weight: bold; display: inline;\">Processo de concepção da informação</span></p></div>', '600px', '40px', 'auto', 'auto', 'editable-item', 0, NULL, '2026-10-05 23:14:08', 'card_1788571380593_ckd4ab'),
(1403759, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 200px; width: 660px; height: auto; overflow: visible;\" data-card-id=\"card_1788571386543_6nek1o\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer; text-align: center;\" class=\"\">O que é um DADO (Em Banco de Dados)</h3><p style=\"cursor: pointer;\" class=\"\">Um dado é uma informação distinta de um aglomerado maior de dados, é considerado um elemento bruto do qual não foi processado para obter uma informação, (EX: um numero em uma planilha, um nome em uma planilha, <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">etc</span>) tudo que não é processado, e por tanto não tem uma contextualização prévia é considerado um dado.</p></div></div>', '700px', '200px', '660px', 'auto', 'editable-item', 1, NULL, '2026-10-05 23:14:08', 'card_1788571386543_6nek1o'),
(1403760, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 900px; width: 660px; height: auto;\" data-card-id=\"card_1788571421548_moblxq\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer; text-align: center;\" class=\"\">O que é um Informação (Em Banco de Dados)</h3><p style=\"cursor: pointer;\" class=\"\">Uma informação é um substrato de um processamento, portanto utilizamos dados do banco de dados para obtermos um resultado, seja obter uma média arrítimetica ou até mesmo o conjunto de colunas que trazem uma objetificação do dado, portanto tornando um conjunto de dados em uma informação <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">úsavel</span></p></div></div>', '700px', '900px', '660px', 'auto', 'editable-item', 2, NULL, '2026-10-05 23:14:08', 'card_1788571421548_moblxq'),
(1403761, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 700px; top: 540px; width: 660px; height: auto;\" data-card-id=\"card_1788571426015_jgcusv\"><div class=\"vscode-explanation\" style=\"\"><h3 style=\"cursor: pointer; text-align: center;\" class=\"\">Processamento (Em Banco de dados)</h3><p style=\"cursor: pointer;\" class=\"\">O processamento é a conversão dos dados presentes no banco de dados para algo abstrato onde nós, humanos, podemos entender de forma racional, e consequentemente utilizarmos do produto em futuras decisões ou avaliar casos/situações.</p></div></div>', '700px', '540px', '660px', 'auto', 'editable-item', 3, NULL, '2026-10-05 23:14:08', 'card_1788571426015_jgcusv'),
(1403762, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 100px; top: 200px; width: 500px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788571479052_odr38p\" data-initialized=\"true\"><p style=\"padding: 8px; margin: 0px; cursor: pointer;\" class=\"\">Podemos dizer que cada <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">celula</span> da tabela representa um dado sem caracterização prévia, se olharmos de forma individual temos um dado, se olharmos o coletivo (linha) teremos uma informação.</p></div>', '100px', '200px', '500px', 'auto', 'editable-item', 4, NULL, '2026-10-05 23:14:08', 'card_1788571479052_odr38p'),
(1403763, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 100px; top: 400px; width: auto; max-width: 90%; height: auto;\" data-card-id=\"card_1788571516808_x4lcx9\" data-initialized=\"true\"><div class=\"table-responsive\" style=\"\"><table class=\"table table-striped-columns styled-table\" style=\"\"><thead style=\"\"><tr style=\"\"><th style=\"cursor: pointer;\">#</th><th style=\"cursor: pointer;\">Nome</th><th style=\"cursor: pointer;\" class=\"active-editing\">nota</th><th style=\"cursor: pointer;\">Status</th></tr></thead><tbody style=\"\"><tr style=\"\"><td style=\"cursor: pointer;\">1</td><td style=\"cursor: pointer;\" class=\"\">Wagner</td><td style=\"cursor: pointer;\" class=\"active-editing\">87,5</td><td style=\"cursor: pointer;\"><span class=\"status active\" style=\"\">Ativo</span></td></tr></tbody></table></div><div class=\"d-flex gap-2 mt-2 flex-wrap table-toolbar\">\n            <button class=\"btn btn-sm btn-outline-primary\">➕ Linha</button>\n            <button class=\"btn btn-sm btn-outline-primary\">➕ Coluna</button>\n            <button class=\"btn btn-sm btn-outline-danger\">➖ Linha</button>\n            <button class=\"btn btn-sm btn-outline-danger\">➖ Coluna</button>\n            <button class=\"btn btn-sm btn-success\">✅ Finalizar</button>\n          </div></div>', '100px', '400px', 'auto', 'auto', 'editable-item', 5, NULL, '2026-10-05 23:14:08', 'card_1788571516808_x4lcx9'),
