(1403765, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 1420px; top: 340px; width: 520px; max-width: 90%; height: auto; overflow: visible;\" data-card-id=\"card_1788571685648_rqktsz\" data-initialized=\"true\"><p style=\"padding: 8px; margin: 0px; cursor: pointer;\" class=\"\" c=\"\">Podemos dizer que a última linha, que representa  o MG (Média Geral), como uma informação, portanto fruto do processamento dos dados</p></div>', '1420px', '340px', '520px', 'auto', 'editable-item', 7, NULL, '2026-10-05 23:14:08', 'card_1788571685648_rqktsz'),
