(1403767, 284980, '<div class=\"editable-item\" style=\"position: absolute; left: 120px; top: 640px; width: 520px; height: auto;\" data-card-id=\"card_1788571711383_ofdko5\"><p style=\"padding: 8px; margin: 0px; cursor: pointer;\" class=\"\">Cada linha representa um conjunto de dados, portanto constitui uma informação que podemos usar para diversas finalidades, por fim, na ultima linha temos um substrato do processamento, uma informação que usa de dados de seletas <span class=\"spell-error\" title=\"Clique para ver sugestões\" data-suggesti=\"\" style=\"text-decoration: underline wavy rgb(255, 107, 107); cursor: pointer;\">celulas</span> para obtermos outra informação.</p></div>', '120px', '640px', '520px', 'auto', 'editable-item', 9, NULL, '2026-10-05 23:14:08', 'card_1788571711383_ofdko5');
