(1403814, 284994, '<div class=\"editable-item\" style=\"position: absolute; left: 20px; top: 200px; width: 1200px; height: auto;\" data-card-id=\"card_1791237756645_dpfoyj\">\n    <div class=\"image-card-container\" style=\"position: relative; width: 100%; height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; cursor: pointer;\">\n      <div class=\"image-placeholder\" style=\"width: 100%; min-height: 160px; border: 2px dashed var(--border-subtle); border-radius: 12px; display: none; flex-direction: column; align-items: center; justify-content: center; gap: 8px; color: var(--text-muted); transition: 0.3s;\">\n        <i class=\"bi bi-image\" style=\"font-size: 40px;\"></i>\n        <span style=\"font-size: 13px;\">Clique ou arraste uma imagem</span>\n      </div>\n      <img class=\"image-preview\" style=\"display: block; max-width: 100%; max-height: 100%; border-radius: 8px;\" src=\"data:image/jpeg;base64,\">\n      <div class=\"image-actions\" style=\"position: absolute; top: 10px; right: 10px; display: none; gap: 6px; z-index: 30;\">\n        <button class=\"btn-change-image\" title=\"Trocar imagem\" style=\"background: rgba(0, 0, 0, 0.6); color: rgb(255, 255, 255); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 50%; width: 28px; height: 28px; cursor: pointer; font-size: 14px; display: flex; align-items: center; justify-content: center;\">\n          <i class=\"bi bi-arrow-repeat\" style=\"\"></i>\n        </button>\n        <button class=\"btn-remove-image\" title=\"Remover imagem\" style=\"background: rgba(0, 0, 0, 0.6); color: rgb(255, 255, 255); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 50%; width: 28px; height: 28px; cursor: pointer; font-size: 14px; display: flex; align-items: center; justify-content: center;\">\n          <i class=\"bi bi-x-lg\" style=\"\"></i>\n        </button>\n      </div>\n      <div class=\"image-caption\" c=\"\" style=\"display: block; margin-top: 8px; font-size: 13px; color: var(--text-secondary); background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; outline: none; width: 100%; text-align: center; cursor: pointer; padding: 4px; min-height: 22px;\">Hologramas</div>\n    </div>\n  </div>', '20px', '200px', '1200px', 'auto', 'editable-item', 2, NULL, '2026-10-05 23:14:08', 'card_1791237756645_dpfoyj');
