(1403817, 284994, '<div class=\"editable-item\" data-card-id=\"card_1791241801685_7jn939\" style=\"position: absolute; left: 1480px; top: 1200px; width: 340px; max-width: 90%; background: var(--bg-surface); border-radius: 16px; padding: 20px 22px; box-shadow: var(--shadow-card); border: 1px solid var(--border-subtle); transition: 0.3s; height: auto;\" data-card-type=\"checklist\" data-state=\"{&quot;type&quot;:&quot;checklist&quot;,&quot;tasks&quot;:[{&quot;id&quot;:1791241801686,&quot;text&quot;:&quot;Definir objetivos do projeto&quot;,&quot;done&quot;:false,&quot;category&quot;:&quot;???? Planejamento&quot;},{&quot;id&quot;:1791241801687,&quot;text&quot;:&quot;Criar wireframes&quot;,&quot;done&quot;:false,&quot;category&quot;:&quot;???? Design&quot;},{&quot;id&quot;:1791241801688,&quot;text&quot;:&quot;Desenvolver protótipo&quot;,&quot;done&quot;:false,&quot;category&quot;:&quot;???? Desenvolvimento&quot;},{&quot;id&quot;:1791241801689,&quot;text&quot;:&quot;Testar com usuários&quot;,&quot;done&quot;:false,&quot;category&quot;:&quot;???? QA&quot;},{&quot;id&quot;:1791241801690,&quot;text&quot;:&quot;Lançar versão 1.0&quot;,&quot;done&quot;:false,&quot;category&quot;:&quot;???? Lançamento&quot;}],&quot;title&quot;:&quot;Caasdashasdecklist&quot;}\" data-initialized=\"true\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n        <span class=\"checklist-counter\" style=\"font-size:12px; color:var(--text-muted);\">0/5 concluídos</span>\n      </div>\n      <div style=\"margin-bottom:12px;\">\n        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;\">\n          <span style=\"font-size:11px; color:var(--text-muted);\">Progresso</span>\n          <span class=\"progress-text\" style=\"font-size:12px; font-weight:600; color:#4a7cf7;\">0%</span>\n        </div>\n        <div style=\"width:100%; height:6px; background:var(--bg-elevated); border-radius:4px; overflow: